// Decodes the fetched file and returns one item per post that's due to fire,
// with tweet text pre-built and hard-capped at 280 chars (X rejects longer).
const fetched = $input.first().json;
const sha = fetched.sha;
const decoded = Buffer.from(fetched.content, 'base64').toString('utf-8');
const queue = JSON.parse(decoded);
const now = Date.now();

const due = queue.filter(
  (post) => post.status === 'queued' && new Date(post.scheduledFor).getTime() <= now,
);

return due.map((post) => {
  let text = post.title + (post.body ? '\n\n' + post.body : '');
  if (text.length > 280) text = text.slice(0, 277) + '...';
  return { json: { ...post, tweetText: text, _sha: sha, _fullQueue: queue } };
});

// Every item reaching this node already posted successfully (a failed HTTP
// call upstream halts the run, since "Continue On Fail" is off on Post Tweet).
const originalItems = $('Decode & Filter Due Posts').all();
if (originalItems.length === 0) return [];

const postedIds = new Set(originalItems.map((item) => item.json.id));
const sha = originalItems[0].json._sha;
const fullQueue = originalItems[0].json._fullQueue;

const updatedQueue = fullQueue.map((post) =>
  postedIds.has(post.id) ? { ...post, status: 'posted' } : post,
);

const content = Buffer.from(JSON.stringify(updatedQueue, null, 2), 'utf-8').toString('base64');

return [{ json: { sha, content, message: `chore: mark ${postedIds.size} post(s) as posted (n8n)` } }];

// Pulls just the since_id cursor out of the fetched state file, tolerating
// a missing file (first-ever run) or a malformed one — either way this
// resolves to null rather than throwing, so "Get Mentions" can safely
// build its URL without a since_id clause.
const stateFetch = $input.first().json;
let sinceMentionId = null;
if (stateFetch && stateFetch.content) {
  try {
    const decoded = JSON.parse(Buffer.from(stateFetch.content, 'base64').toString('utf-8'));
    sinceMentionId = decoded.sinceMentionId || null;
  } catch {
    sinceMentionId = null;
  }
}
return [{ json: { sinceMentionId } }];

// Flattens the mentions response into one item per new mention, attaching
// the author's @handle. An empty/missing `data` array (nothing new since
// since_id) returns [] — every node downstream is per-item and simply
// won't execute this run, so nothing gets committed for a no-op poll.
const res = $input.first().json;
const mentions = res.data || [];
if (mentions.length === 0) return [];

const users = (res.includes && res.includes.users) || [];
const usernameById = new Map(users.map((u) => [u.id, u.username]));

return mentions.map((m) => ({
  json: {
    mentionId: m.id,
    mentionText: m.text,
    mentionAuthor: usernameById.get(m.author_id) || 'there',
  },
}));

// Small on-brand template bank — no LLM node, so no extra API cost or
// unreviewed AI text. Edit these lines any time to change tone; they're
// the only thing that decides what gets auto-posted.
const templates = [
  "Noted, @{name}. Building beats talking about building.",
  "@{name} — logged. Back to the work.",
  "Appreciate the signal, @{name}. Onward.",
  "@{name} — heard. No detours today.",
  "Real one, @{name}. Keep showing up.",
];
const author = $json.mentionAuthor;
const text = templates[Math.floor(Math.random() * templates.length)].replace('{name}', author);
return { json: { ...$json, replyText: text } };

// Merges this run's replies into the persisted log + advances the since_id
// cursor. Reads sha/prior state straight from "Fetch Automation State" and
// this run's drafts/results by node name, the same pattern Flow A uses —
// no reliance on HTTP Request nodes preserving upstream fields in .json.
const drafts = $('Build Reply Text').all();
if (drafts.length === 0) return [];

const posted = $('Post Reply').all();
const stateFetch = $('Fetch Automation State (GitHub)').first().json;

let sha;
let existingLog = [];
let sinceMentionId = null;
if (stateFetch && stateFetch.content) {
  sha = stateFetch.sha;
  const decoded = JSON.parse(Buffer.from(stateFetch.content, 'base64').toString('utf-8'));
  existingLog = decoded.replyLog || [];
  sinceMentionId = decoded.sinceMentionId || null;
}

const newEntries = drafts.map((d, i) => ({
  mentionId: d.json.mentionId,
  mentionAuthor: d.json.mentionAuthor,
  mentionText: d.json.mentionText,
  replyText: d.json.replyText,
  replyTweetId: (posted[i] && posted[i].json.data && posted[i].json.data.id) || '',
  repliedAt: new Date().toISOString(),
}));

// Cap at 200 entries so the file doesn't grow unbounded — plenty for the
// Command Deck's Replies tab, which only ever shows the most recent 20.
const mergedLog = [...newEntries, ...existingLog].slice(0, 200);

// X's snowflake IDs are numeric strings where a larger value is always
// newer — compare as BigInt so this doesn't break on IDs too large for
// a JS Number.
const maxId = drafts.reduce((max, d) => {
  const id = d.json.mentionId;
  return !max || BigInt(id) > BigInt(max) ? id : max;
}, sinceMentionId);

const payload = { sinceMentionId: maxId, replyLog: mergedLog };
const content = Buffer.from(JSON.stringify(payload, null, 2), 'utf-8').toString('base64');

return [{ json: { sha, content, message: `chore: log ${newEntries.length} auto-repl${newEntries.length === 1 ? 'y' : 'ies'} (n8n)` } }];

// Shapes real X data into exactly the LiveMetricsFile shape the Command
// Deck expects (src/lib/types.ts). Revenue is deliberately left at 0 here —
// X's API doesn't expose ad revenue or tips at any access level, so that
// stays hand-logged in Mission Log, same as before this automation existed.
const user = $('Get User').first().json.data;
const tweets = $input.first().json.data || [];

const posts = tweets.map((t) => {
  const m = t.public_metrics || {};
  const impressions = m.impression_count || 0;
  const engagementCount = (m.like_count || 0) + (m.retweet_count || 0) + (m.reply_count || 0) + (m.quote_count || 0);
  const engagement = impressions > 0 ? (engagementCount / impressions) * 100 : 0;
  return {
    id: t.id,
    title: t.text.length > 80 ? t.text.slice(0, 77) + '...' : t.text,
    vertical: 'Threads',
    impressions,
    engagement: Math.round(engagement * 10) / 10,
    revenue: 0,
    postedAt: t.created_at,
  };
});

const now = Date.now();
const weekAgo = now - 7 * 24 * 60 * 60 * 1000;
const dayAgo = now - 24 * 60 * 60 * 1000;
const postedThisWeek = posts.filter((p) => new Date(p.postedAt).getTime() >= weekAgo);
const impressions24h = posts
  .filter((p) => new Date(p.postedAt).getTime() >= dayAgo)
  .reduce((sum, p) => sum + p.impressions, 0);
const impressions7d = postedThisWeek.reduce((sum, p) => sum + p.impressions, 0);
const avgEngagement = posts.length
  ? posts.reduce((sum, p) => sum + p.engagement, 0) / posts.length
  : 0;

const stats = {
  followers: (user.public_metrics && user.public_metrics.followers_count) || 0,
  impressions24h,
  impressions7d,
  engagement: Math.round(avgEngagement * 10) / 10,
  // Not available from the X API at any tier — stays hand-logged.
  revenueX: 0,
  revenueTips: 0,
  revenueOther: 0,
  postsWeek: postedThisWeek.length,
  sparkline: posts
    .slice()
    .reverse()
    .map((p) => p.impressions),
};

const payload = { updatedAt: new Date().toISOString(), stats, posts };
return [{ json: payload }];

const payload = $('Build Live Metrics Payload').first().json;
const existing = $input.first().json;
const sha = existing && existing.sha ? existing.sha : undefined;
const content = Buffer.from(JSON.stringify(payload, null, 2), 'utf-8').toString('base64');
return [{ json: { sha, content, message: `chore: sync live metrics (${payload.updatedAt})` } }];

// Curated accounts for selective engagement — edit this list any time.
const handles = ['naval','balajis','pmarca','garrytan','TheRestHistory','DominicSandbrook','RichardDawkins','neiltyson','chamath','Jason','CulturalTutor','willwilkinson','RoryStewartUK','nntaleb','yhazony','saifedean'];
return [{ json: { handles } }];

const res = $input.first().json;
const users = res.data || [];
return users.map((u) => ({ json: { id: u.id, username: u.username } }));

// One candidate per account at most, per scan — recent, substantial (not a
// one-liner), never a retweet/reply (excluded at the API level already).
const accounts = $('Prepare Account List').all();
const tweetResponses = $('Get Recent Tweets Per Account').all();
const sixteenHoursMs = 16 * 60 * 60 * 1000;

const fresh = [];
accounts.forEach((acc, i) => {
  const res = tweetResponses[i] && tweetResponses[i].json;
  const tweets = (res && res.data) || [];
  const candidate = tweets.find((t) => {
    const age = Date.now() - new Date(t.created_at).getTime();
    return age <= sixteenHoursMs && t.text && t.text.length >= 60;
  });
  if (candidate) {
    fresh.push({
      accountUsername: acc.json.username,
      tweetId: candidate.id,
      text: candidate.text,
      createdAt: candidate.created_at,
      url: `https://x.com/${acc.json.username}/status/${candidate.id}`,
      discoveredAt: new Date().toISOString(),
    });
  }
});

const existingFetch = $('Fetch Existing Candidates (GitHub)').first().json;
let sha;
let existing = [];
if (existingFetch && existingFetch.content) {
  sha = existingFetch.sha;
  try {
    existing = JSON.parse(Buffer.from(existingFetch.content, 'base64').toString('utf-8'));
  } catch {
    existing = [];
  }
}

// Drop stale candidates automatically if they're still sitting unreplied
// after 3 days, and never keep two entries for the same tweet.
const seenIds = new Set(fresh.map((c) => c.tweetId));
const keptExisting = existing.filter((c) => !seenIds.has(c.tweetId));
const threeDaysAgoMs = Date.now() - 3 * 24 * 60 * 60 * 1000;
const merged = [...fresh, ...keptExisting]
  .filter((c) => new Date(c.discoveredAt || c.createdAt).getTime() >= threeDaysAgoMs)
  .slice(0, 40);

const content = Buffer.from(JSON.stringify(merged, null, 2), 'utf-8').toString('base64');
return [{ json: { sha, content, message: `chore: refresh engagement candidates (${merged.length})` } }];
